import java.util.List;
import java.util.Random;


public abstract class Animal extends Entity {


	private static final Random rand = Randomizer.getRandom();

	private boolean alive;

	private int age;

	private Gender gender;

	private boolean nocturnal;

	private int foodChainLevel;

	private int foodValue;

	private int foodLevel;

	private boolean sick;

	private int sickProbability;

	private int recoverProbability;

	private int sickStep;

	private int maxSickStep;


	public Animal(Field field, Location location) {
		super(field, location);
		alive = true;
		gender = Gender.randomGender();
		sickProbability = 16;
	}


	@Override
	protected void placeInField(Field field, Location location) {
		field.placeAnimal(this, location);
	}


	protected abstract void normalAct(List<Animal> newAnimals);


	public void act(List<Animal> newAnimals, TimeCycle time) {
		incrementAge();
		incrementHunger();
		battleSickness();
		if (isAlive()) {
			if ((time == TimeCycle.NIGHT && isNocturnal()) || (time == TimeCycle.DAY && !isNocturnal())) {
				normalAct(newAnimals);
			}
		}
	}


	protected void incrementAge() {
		age++;
		if (age > getMaxAge()) {
			setDead();
		}
	}


	private boolean canBreed() {
		if (age < getBreedingAge()) {
			return false;
		}
		Field field = getField();
		List<Location> adjacent = field.adjacentAnimalLocations(getLocation());
		for (Location where : adjacent) {
			Object animal = field.getAnimalAt(where);
			if (animal instanceof Animal) {
				Animal animalNear = (Animal) animal;
				if (animalNear.getClass() == this.getClass() && getGender() != animalNear.getGender()) {
					return true;
				}
			}
		}
		return false;
	}


	private int breed() {
		if (canBreed() && rand.nextDouble() <= getBreedingProbability()) {
			return rand.nextInt(getMaxLitterSize()) + 1;
		}
		return 0;
	}


	protected void giveBirth(List<Animal> newAnimals) {
		if (getGender() == Gender.FEMALE) {
			Field field = getField();
			List<Location> free = field.getFreeAnimalAdjacentLocations(getLocation());
			int births = breed();
			for (int b = 0; b < births && !free.isEmpty(); b++) {
				Location loc = free.remove(0);
				newAnimals.add(createNewAnimal(false, field, loc));
			}
		}
	}


	protected boolean isAlive() {
		return alive;
	}


	protected void setDead() {
		alive = false;
		if (getLocation() != null) {
			getField().clear(getLocation());
			detach();
		}
	}


	protected void becomeSick() {
		if (!isSick() && rand.nextInt(getSickProbability()) == 1) {
			sick = true;
		}
	}


	protected void notSick() {
		if (isSick() && rand.nextInt(getRecoverProbability()) == 1) {
			sick = false;
			sickStep = 0;
		}
	}


	protected void battleSickness() {
		if (isSick()) {
			if (sickStep >= maxSickStep) {
				setDead();
				return;
			}
			sickStep++;
			Field field = getField();
			if (field != null) {
				for (Location where : field.adjacentAnimalLocations(getLocation())) {
					Object animal = field.getAnimalAt(where);
					if (animal instanceof Animal) {
						Animal nearAnimal = (Animal) animal;
						if (nearAnimal.getClass() == this.getClass()) {
							nearAnimal.becomeSick();
						}
					}
				}
				notSick();
			}
		} else {
			becomeSick();
		}
	}


	protected void incrementHunger() {
		foodLevel--;
		if (foodLevel <= 0) {
			setDead();
		}
	}


	protected void setNocturnal(boolean value) {
		nocturnal = value;
	}


	protected int getSickProbability() {
		return sickProbability;
	}


	protected void setSickProbability(int inputValue) {
		sickProbability = inputValue;
	}


	protected int getRecoverProbability() {
		return recoverProbability;
	}


	protected void setRecoverProbability(int inputValue) {
		recoverProbability = inputValue;
	}


	protected Gender getGender() {
		return gender;
	}


	protected int getFoodChainLevel() {
		return foodChainLevel;
	}


	protected void setFoodChainLevel(int level) {
		foodChainLevel = level;
	}


	protected int getFoodValue() {
		return foodValue;
	}


	protected void setFoodValue(int value) {
		foodValue = value;
	}


	protected boolean isNocturnal() {
		return nocturnal;
	}


	protected boolean isSick() {
		return sick;
	}


	protected void setAge(int age) {
		this.age = age;
	}


	protected int getFoodLevel() {
		return foodLevel;
	}


	protected void setFoodLevel(int foodLevel) {
		this.foodLevel = foodLevel;
	}


	protected void setMaxSickStep(int inputValue) {
		this.maxSickStep = inputValue;
	}


	protected abstract int getBreedingAge();


	protected abstract int getMaxAge();


	protected abstract double getBreedingProbability();


	protected abstract int getMaxLitterSize();


	protected abstract Animal createNewAnimal(boolean randomAge, Field field, Location loc);
}

