27			super.increaseStage(climate);
28			Season season = climate.getCurrentSeason();
29			if ((season == Season.SPRING || season == Season.AUTUMN) && getStage() > 2) {
30				setStage(2);
31			} else if (season == Season.SUMMER && getStage() > 3) {
32				setStage(3);
33			} else if (season == Season.WINTER && getStage() > 1) {
34				setStage(1);
35			}
36		}
