40		protected Color getObjectColor(Climate climate) {
41			switch (climate.getCurrentSeason()) {
42				case SPRING:
43					if (getStage() == 2) {
44						return new Color(34, 140, 61);
45					} else if (getStage() == 1) {
46						return new Color(68, 201, 104);
47					} else {
48						return new Color(131, 101, 57);
49					}
50				case SUMMER:
51					if (getStage() == 3) {
52						return new Color(11, 102, 35);
53					} else if (getStage() == 2) {
54						return new Color(34, 140, 61);
55					} else if (getStage() == 1) {
